content.text:
**Summary:** The ticket's symptoms (slow or failing requests) trace to two faults. Ts-basic-service's outbound HTTP calls are held for seconds, which slows travel, travel2 and preserve. Separately, ts-route-plan-service's outbound POSTs abort, producing failures that surface at ts-travel-plan-service and then at ts-ui-dashboard. I'm treating the route-plan fault as independent: its failures happen in the first minute, before basic's slowdown begins around 138 s.

```json
{
  "root_causes": [
    {
      "service": "ts-basic-service",
      "fault_kind": "http_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name AS callee, c.span_name, c.attr_span_kind, COUNT(*) n, ROUND(AVG(CAST(p.duration AS DOUBLE))/1e6,1) cli_ms, ROUND(AVG(CAST(c.duration AS DOUBLE))/1e6,1) srv_ms FROM abnormal_traces p JOIN abnormal_traces c ON c.parent_span_id=p.span_id WHERE p.service_name='ts-basic-service' AND p.attr_span_kind='Client' AND p.duration>5e8 GROUP BY ALL ORDER BY n DESC LIMIT 12",
          "claim": "Slow (>500ms) basic outbound GET calls took seconds client-side while callee server spans stayed around 4 ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, FLOOR(EXTRACT(EPOCH FROM (time - (SELECT MIN(time) FROM abnormal_traces)))/60) AS min_idx, COUNT(*) n, ROUND(quantile_cont(duration,0.5)/1e6,1) p50_ms, ROUND(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-basic-service' AND span_name='BasicController.queryForTravel' GROUP BY ALL ORDER BY 2",
          "claim": "Basic queryForTravel p95 grows from about 35 ms to over 1 s after minute 2 of the window."
        }
      ]
    },
    {
      "service": "ts-route-plan-service",
      "fault_kind": "http_aborted",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT attr_status_code, COUNT(*) n, ROUND(quantile_cont(duration,0.5)/1e6,1) p50_ms FROM abnormal_traces WHERE service_name='ts-route-plan-service' AND attr_span_kind='Client' AND span_name='POST' GROUP BY 1",
          "claim": "74 of route-plan's outbound POSTs end in Error after about 1 ms, while the rest succeed at about 70 ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT COUNT(*) AS failed_posts, SUM(CASE WHEN c.span_id IS NULL THEN 1 ELSE 0 END) AS without_child_span FROM abnormal_traces p LEFT JOIN abnormal_traces c ON c.parent_span_id=p.span_id WHERE p.service_name='ts-route-plan-service' AND p.attr_span_kind='Client' AND p.span_name='POST' AND p.attr_status_code='Error'",
          "claim": "Failed route-plan POSTs have no child server span, so the requests were cut before reaching the callee."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-basic-service",
      "to": "ts-travel-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name AS caller, c.service_name AS callee, c.span_name, COUNT(*) n, ROUND(quantile_cont(p.duration,0.95)/1e6,1) cli_p95_ms, ROUND(quantile_cont(c.duration,0.95)/1e6,1) srv_p95_ms FROM abnormal_traces p JOIN abnormal_traces c ON c.parent_span_id=p.span_id WHERE p.service_name='ts-travel-service' AND c.service_name='ts-basic-service' AND p.attr_span_kind='Client' GROUP BY ALL",
          "claim": "Travel's calls into basic show a p95 of about 187 ms, with basic's server spans far below the client durations."
        }
      ]
    },
    {
      "from": "ts-basic-service",
      "to": "ts-travel2-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name AS caller, c.service_name AS callee, COUNT(*) n, ROUND(quantile_cont(p.duration,0.95)/1e6,1) cli_p95_ms, ROUND(quantile_cont(c.duration,0.95)/1e6,1) srv_p95_ms FROM abnormal_traces p JOIN abnormal_traces c ON c.parent_span_id=p.span_id WHERE p.service_name='ts-travel2-service' AND c.service_name='ts-basic-service' AND p.attr_span_kind='Client' GROUP BY ALL",
          "claim": "Travel2's calls into basic show client p95 well above basic's server p95, consistent with basic's outbound slowness."
        }
      ]
    },
    {
      "from": "ts-basic-service",
      "to": "ts-preserve-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name AS callee, c.span_name, COUNT(*) n, ROUND(quantile_cont(p.duration,0.95)/1e6,1) cli_p95, ROUND(quantile_cont(c.duration,0.95)/1e6,1) srv_p95 FROM abnormal_traces p JOIN abnormal_traces c ON c.parent_span_id=p.span_id WHERE p.service_name='ts-preserve-service' AND p.attr_span_kind='Client' GROUP BY ALL ORDER BY cli_p95 DESC LIMIT 8",
          "claim": "Preserve's calls to basic travel show client p95 near 187 ms against about 62 ms server-side."
        }
      ]
    },
    {
      "from": "ts-travel-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name AS callee, COUNT(*) n, ROUND(quantile_cont(c.duration,0.95)/1e6,1) srv_p95_ms FROM abnormal_traces p JOIN abnormal_traces c ON c.parent_span_id=p.span_id WHERE p.service_name='ts-route-plan-service' AND p.attr_span_kind='Client' AND c.service_name IN ('ts-travel-service','ts-travel2-service') GROUP BY 1",
          "claim": "Route-plan's calls into travel and travel2 have server-side p95 over 1.2 s, up from about 400 ms."
        }
      ]
    },
    {
      "from": "ts-travel2-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name AS callee, COUNT(*) n, ROUND(quantile_cont(c.duration,0.95)/1e6,1) srv_p95_ms FROM abnormal_traces p JOIN abnormal_traces c ON c.parent_span_id=p.span_id WHERE p.service_name='ts-route-plan-service' AND p.attr_span_kind='Client' AND c.service_name='ts-travel2-service' GROUP BY 1",
          "claim": "Route-plan calls to travel2 slow sharply in the abnormal window."
        }
      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, attr_span_kind, attr_http_response_status_code AS code, COUNT(*) n FROM abnormal_traces WHERE service_name='ts-travel-plan-service' AND attr_span_kind='Client' AND attr_status_code='Error' GROUP BY 1,2,3",
          "claim": "Travel-plan's calls to route-plan return HTTP 500 for 74 requests, mirroring route-plan's aborted POSTs."
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, COUNT(*) n, SUM(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE attr_span_kind='Server' AND service_name IN ('ts-ui-dashboard','ts-travel-plan-service') AND span_name LIKE '%travelPlan%' GROUP BY 1,2 ORDER BY errs DESC",
          "claim": "User-facing travelPlan requests at ui-dashboard fail with the same counts as travel-plan's server errors."
        }
      ]
    },
    {
      "from": "ts-preserve-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name AS caller, c.service_name AS callee, COUNT(*) n, ROUND(quantile_cont(c.duration,0.95)/1e6,1) srv_p95_ms FROM abnormal_traces p JOIN abnormal_traces c ON c.parent_span_id=p.span_id WHERE p.service_name='ts-ui-dashboard' AND c.service_name='ts-preserve-service' AND p.attr_span_kind='Client' GROUP BY ALL",
          "claim": "Ui-dashboard's preserve calls show server-side p95 rising to about 1.8 s in the abnormal window."
        }
      ]
    }
  ]
}
```
